import { expect, test } from "bun:test";
import { existsSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { safeWindowsFileName } from "./platform.js";

test("renames a reserved device name", () => {
	expect(safeWindowsFileName("con")).toBe("_con");
});

test("renames every reserved Windows device name", () => {
	const reserved = [
		"CON",
		"PRN",
		"AUX",
		"NUL",
		"com0",
		"COM1",
		"com9",
		"lpt0",
		"LPT1",
		"lpt9",
		"COM¹",
		"COM²",
		"COM³",
		"LPT¹",
		"LPT²",
		"LPT³",
	];
	for (const name of reserved) {
		expect(safeWindowsFileName(name)).toBe(`_${name}`);
	}
	expect(safeWindowsFileName("readme")).toBe("readme");
	expect(safeWindowsFileName("com10")).toBe("com10");
});

test.skipIf(process.platform !== "win32")(
	"creates the replacement on Windows",
	() => {
		const replacement = safeWindowsFileName("con");
		const dir = mkdtempSync(join(tmpdir(), "safe-win-"));
		const filePath = join(dir, replacement);
		writeFileSync(filePath, "ok");
		expect(existsSync(filePath)).toBe(true);
		rmSync(dir, { recursive: true, force: true });
	},
);
